-- Cabo Crew D1 schema (already applied to the cabo-crew database).
CREATE TABLE IF NOT EXISTS families (id TEXT PRIMARY KEY, name TEXT NOT NULL, token TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS members (id TEXT PRIMARY KEY, family_id TEXT NOT NULL, name TEXT NOT NULL, age INTEGER NOT NULL, pos INTEGER NOT NULL DEFAULT 0, fig BLOB, fig_mime TEXT, fig_v INTEGER NOT NULL DEFAULT 0, fig_kind TEXT, grp TEXT NOT NULL DEFAULT 'adult');  -- age is unused (kept for the original table)
CREATE INDEX IF NOT EXISTS members_family ON members(family_id);
CREATE TABLE IF NOT EXISTS budget (day TEXT PRIMARY KEY, n INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS plan_items (id TEXT PRIMARY KEY, day INTEGER NOT NULL, pos REAL NOT NULL, t TEXT NOT NULL DEFAULT '', title TEXT NOT NULL, note TEXT NOT NULL DEFAULT '', place TEXT NOT NULL DEFAULT 'palace', who TEXT NOT NULL DEFAULT '', icon TEXT NOT NULL DEFAULT 'sparkles', opt INTEGER NOT NULL DEFAULT 0, family_id TEXT, updated_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS plan_day ON plan_items(day, pos);
CREATE TABLE IF NOT EXISTS messages (id INTEGER PRIMARY KEY AUTOINCREMENT, family_id TEXT, member_id TEXT, name TEXT NOT NULL, fam TEXT NOT NULL DEFAULT '', kind TEXT NOT NULL DEFAULT 'text', text TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS meta (k TEXT PRIMARY KEY, v TEXT);
CREATE TABLE IF NOT EXISTS visits (device TEXT PRIMARY KEY, family_id TEXT, first_seen INTEGER NOT NULL, last_seen INTEGER NOT NULL, opens INTEGER NOT NULL DEFAULT 1, device_kind TEXT, place TEXT);
